(function() {
	//#region src/Modules/CrestApps.OrchardCore.Resources/Assets/js/confirm-submit.js
	(function() {
		"use strict";
		document.addEventListener("click", (event) => {
			const button = event.target.closest("button[data-confirm-submit]");
			if (!button || !button.form || button.disabled || button.dataset.confirmed === "true" || typeof window.confirmDialog !== "function") return;
			event.preventDefault();
			window.confirmDialog({
				...button.dataset,
				callback: (confirmed) => {
					if (!confirmed) return;
					button.dataset.confirmed = "true";
					try {
						button.form.requestSubmit(button);
					} finally {
						delete button.dataset.confirmed;
					}
				}
			});
		});
	})();
	//#endregion
})();
